import{_ as r,o as t,c as s,a2 as a}from"./chunks/framework.KobcctIO.js";const p=JSON.parse('{"title":"FAQ et Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/players/troubleshooting.md","filePath":"fr/guide/players/troubleshooting.md"}'),o={name:"fr/guide/players/troubleshooting.md"};function n(i,e,l,u,c,d){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="faq-et-depannage" tabindex="-1">FAQ et Dépannage <a class="header-anchor" href="#faq-et-depannage" aria-label="Permalink to &quot;FAQ et Dépannage&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Support-GitHub%20Issues-blue.svg" alt="Support"><img src="https://img.shields.io/badge/Statut-Open%20Source-green.svg" alt="Statut"></div><p>Ce guide rassemble les solutions aux questions et incidents les plus fréquemment rencontrés lors de l&#39;utilisation de Gens Launcher.</p><hr><h2 id="questions-frequemment-posees-faq" tabindex="-1">Questions Fréquemment Posées (FAQ) <a class="header-anchor" href="#questions-frequemment-posees-faq" aria-label="Permalink to &quot;Questions Fréquemment Posées (FAQ)&quot;">​</a></h2><h3 id="gens-launcher-prend-il-en-charge-les-comptes-hors-ligne" tabindex="-1">Gens Launcher prend-il en charge les comptes hors-ligne ? <a class="header-anchor" href="#gens-launcher-prend-il-en-charge-les-comptes-hors-ligne" aria-label="Permalink to &quot;Gens Launcher prend-il en charge les comptes hors-ligne ?&quot;">​</a></h3><p><strong>Oui.</strong> Bien que nous recommandions l&#39;utilisation d&#39;un compte officiel Microsoft pour profiter des serveurs sécurisés et de la synchronisation de skins, Gens Launcher intègre un mode hors-ligne complet permettant de jouer en local ou sur des réseaux privés.</p><h3 id="pourquoi-windows-affiche-t-il-l-ecran-bleu-smartscreen-lors-de-l-installation" tabindex="-1">Pourquoi Windows affiche-t-il l&#39;écran bleu SmartScreen lors de l&#39;installation ? <a class="header-anchor" href="#pourquoi-windows-affiche-t-il-l-ecran-bleu-smartscreen-lors-de-l-installation" aria-label="Permalink to &quot;Pourquoi Windows affiche-t-il l&#39;écran bleu SmartScreen lors de l&#39;installation ?&quot;">​</a></h3><p>Gens Launcher est un projet indépendant open-source. L&#39;obtention d&#39;un certificat commercial Windows EV coûte plusieurs centaines d&#39;euros par an. Cliquez simplement sur <strong>« Informations complémentaires »</strong> puis sur <strong>« Exécuter quand même »</strong>. L&#39;intégralité du code est vérifiable sur GitHub.</p><h3 id="est-ce-que-mes-identifiants-microsoft-sont-en-securite" tabindex="-1">Est-ce que mes identifiants Microsoft sont en sécurité ? <a class="header-anchor" href="#est-ce-que-mes-identifiants-microsoft-sont-en-securite" aria-label="Permalink to &quot;Est-ce que mes identifiants Microsoft sont en sécurité ?&quot;">​</a></h3><p><strong>Oui, totalement.</strong> Gens Launcher utilise le flux officiel OAuth2 Device Code de Microsoft. Le lanceur ne voit jamais votre mot de passe. Vos jetons de session sont chiffrés sur votre disque via les API sécurisées de votre système d&#39;exploitation (<code>safeStorage</code> ou AES-256-GCM dérivé par PBKDF2 à 600 000 itérations).</p><h3 id="gens-launcher-est-il-gratuit" tabindex="-1">Gens Launcher est-il gratuit ? <a class="header-anchor" href="#gens-launcher-est-il-gratuit" aria-label="Permalink to &quot;Gens Launcher est-il gratuit ?&quot;">​</a></h3><p><strong>Oui, 100% gratuit et sans publicité.</strong> Le projet est distribué sous la licence libre MIT. Il ne comporte aucune télémétrie commerciale ni revente de données.</p><hr><h2 id="problemes-courants-et-solutions" tabindex="-1">Problèmes Courants et Solutions <a class="header-anchor" href="#problemes-courants-et-solutions" aria-label="Permalink to &quot;Problèmes Courants et Solutions&quot;">​</a></h2><h3 id="_1-le-jeu-refuse-de-demarrer-erreur-java-ou-crash-immediat" tabindex="-1">1. Le jeu refuse de démarrer (Erreur Java ou crash immédiat) <a class="header-anchor" href="#_1-le-jeu-refuse-de-demarrer-erreur-java-ou-crash-immediat" aria-label="Permalink to &quot;1. Le jeu refuse de démarrer (Erreur Java ou crash immédiat)&quot;">​</a></h3><ul><li><strong>Vérifiez la version de Java :</strong> Minecraft 1.20.5+ requiert Java 21 ou Java 25. Minecraft 1.18 à 1.20.4 requiert Java 17. Minecraft 1.16 requiert Java 8.<br> Rendez-vous dans les <em>Paramètres de l&#39;Instance</em> et laissez Gens Launcher télécharger automatiquement le bon runtime Java.</li><li><strong>Vérifiez la mémoire vive allouée (RAM) :</strong> Une allocation insuffisante (moins de 2 Go) peut provoquer un <code>java.lang.OutOfMemoryError</code>. Inversement, n&#39;allouez pas plus de la moitié de votre RAM totale système pour éviter de bloquer votre système d&#39;exploitation.</li><li><strong>Incompatibilité de mods :</strong> Consultez l&#39;onglet <em>Logs</em> de l&#39;instance pour identifier le mod responsable du crash (généralement indiqué par <code>CrashReport</code> ou <code>MixinApplyError</code>). Désactivez le mod suspect via l&#39;interrupteur dans l&#39;onglet Mods.</li></ul><h3 id="_2-echec-de-la-synchronisation-cloud-horizon" tabindex="-1">2. Échec de la synchronisation Cloud Horizon <a class="header-anchor" href="#_2-echec-de-la-synchronisation-cloud-horizon" aria-label="Permalink to &quot;2. Échec de la synchronisation Cloud Horizon&quot;">​</a></h3><ul><li><strong>Vérifiez votre connexion réseau :</strong> En cas de coupure Internet, le lanceur active automatiquement son mode hors-ligne et neutralise les appels cloud pour éviter de bloquer l&#39;interface.</li><li><strong>Message « Verrou actif » (horizon.lock) :</strong> Si le jeu a été quitté brutalement ou si l&#39;instance tourne sur un autre ordinateur, un verrouillage de sécurité protège vos fichiers. Si vous êtes certain qu&#39;aucun autre processus ne tourne, vous pouvez débloquer l&#39;instance via le bouton <em>Purger le verrou</em> dans les options avancées.</li><li><strong>Expiration du jeton Cloud :</strong> Si votre compte Google Drive, Dropbox ou OneDrive a révoqué l&#39;accès, déconnectez puis reconnectez simplement le fournisseur dans les <em>Paramètres Horizon</em>.</li></ul><h3 id="_3-problemes-d-installation-sur-macos" tabindex="-1">3. Problèmes d&#39;installation sur macOS <a class="header-anchor" href="#_3-problemes-d-installation-sur-macos" aria-label="Permalink to &quot;3. Problèmes d&#39;installation sur macOS&quot;">​</a></h3><ul><li><strong>Erreur « Impossible d&#39;ouvrir l&#39;application car elle ne provient pas d&#39;un développeur identifié » :</strong> Faites un clic droit sur l&#39;icône de Gens Launcher dans le dossier <code>/Applications</code>, sélectionnez <strong>Ouvrir</strong>, puis confirmez en cliquant sur <strong>Ouvrir</strong>. Cette confirmation n&#39;est nécessaire qu&#39;au premier lancement.</li></ul><hr><h2 id="ou-trouver-de-l-aide" tabindex="-1">Où trouver de l&#39;aide ? <a class="header-anchor" href="#ou-trouver-de-l-aide" aria-label="Permalink to &quot;Où trouver de l&#39;aide ?&quot;">​</a></h2><p>Si votre problème persiste :</p><ol><li>Récupérez les journaux d&#39;erreurs (Logs) depuis le menu <em>Aide / Journaux</em>.</li><li>Ouvrez un ticket transparent sur le <a href="https://github.com/WilliamBossard/Gens-Launcher/issues" target="_blank" rel="noreferrer">Dépôt GitHub Gens-Launcher Issues</a>.</li></ol>',25)])])}const h=r(o,[["render",n]]);export{p as __pageData,h as default};
